1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Damage = {
9	  itemType: string;
10	  amount: number;
11	};
12	
13	export type Incident = {
14	  cause: string;
15	  damages: Damage[];
16	};
17	
18	export type Step = {
19	  op: string;
20	  items?: Item[];
21	  policy?: number;
22	  incident?: Incident;
23	};
24	
25	export type Customer = {
26	  yearsWithMHPCO: number;
27	};
28	
29	export type Scenario = {
30	  customer: Customer;
31	  steps: Step[];
32	};
33	
34	export type QuoteResult = {
35	  premium: number;
36	};
37	
38	export type ClaimResult = {
39	  payout: number;
40	  remainingCap: number;
41	};
42	
43	// A scenario's results are heterogeneous: a quote step yields a premium, a
44	// claim step a payout and the cap left on its policy.
45	export type StepResult = QuoteResult | ClaimResult;
46	
47	export type ScenarioResults = {
48	  results: StepResult[];
49	};
50	
51	// --- Quotes ------------------------------------------------------------------
52	
53	const PROCESSING_FEE = 5;
54	
55	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
56	  sword: 100,
57	  amulet: 60,
58	  staff: 80,
59	  potion: 40,
60	  rune: 25,
61	  moonstone: 25,
62	};
63	
64	// Charged on every quote, unconditionally — it is the cost of assessing the
65	// items, not a penalty for being a new customer. Named "first insurance" in
66	// some of the domain material, which misleads: it does not depend on customer
67	// history or on the quote's position in the scenario.
68	const INITIAL_ASSESSMENT_SURCHARGE_PERCENT = 10;
69	
70	const WHOLE_PERCENT = 100;
71	
72	const percentOf = (amount: number, percent: number): number =>
73	  (amount * percent) / WHOLE_PERCENT;
74	
75	// The tables keyed by item type cover exactly the types the MHPCO insures.
76	// Anything else is not a mispriced item, it is not an item at all, so a lookup
77	// miss is an error rather than a zero. `priceName` names the price the table
78	// holds, so the rejection can say which one the item had none of.
79	const lookUpByItemType = (
80	  table: Record<string, number>,
81	  item: Item,
82	  priceName: string,
83	): number => {
84	  const value = table[item.type];
85	
86	  if (value === undefined) {
87	    throw new Error(`unknown item type "${item.type}": no ${priceName}`);
88	  }
89	
90	  return value;
91	};
92	
93	const itemBasePremium = (item: Item): number =>
94	  lookUpByItemType(BASE_PREMIUM_BY_TYPE, item, "base premium");
95	
96	const BLOCK_SIZE = 3;
97	
98	const BLOCK_PREMIUM = 60;
99	
100	const sumOf = (amounts: number[]): number =>
101	  amounts.reduce((sum, amount) => sum + amount, 0);
102	
103	const formsABlock = (items: Item[]): boolean => items.length === BLOCK_SIZE;
104	
105	const sumOfItemBasePremiums = (items: Item[]): number =>
106	  sumOf(items.map(itemBasePremium));
107	
108	// Items of the same type are "alike" and are priced together, so the policy
109	// base premium is computed group by group rather than item by item.
110	const alikeGroups = (items: Item[]): Item[][] => {
111	  const groupsByType = new Map<string, Item[]>();
112	
113	  for (const item of items) {
114	    groupsByType.set(item.type, [...(groupsByType.get(item.type) ?? []), item]);
115	  }
116	
117	  return [...groupsByType.values()];
118	};
119	
120	const alikeGroupBasePremium = (alikeItems: Item[]): number =>
121	  formsABlock(alikeItems)
122	    ? BLOCK_PREMIUM
123	    : sumOfItemBasePremiums(alikeItems);
124	
125	const policyBasePremium = (items: Item[]): number =>
126	  sumOf(alikeGroups(items).map(alikeGroupBasePremium));
127	
128	const roundPremiumInMHPCOsFavor = (amount: number): number =>
129	  Math.ceil(amount);
130	
131	// The inputs a single quote is computed from: `items` drives the base premium
132	// and item-scoped surcharges, `customer` and `precedingQuoteCount` drive the
133	// policy-wide modifiers. The count is of preceding QUOTE steps, not of steps in
134	// general — a claim step is not a contract and must not trigger the follow-up
135	// discount.
136	type QuoteRequest = {
137	  customer: Customer;
138	  items: Item[];
139	  precedingQuoteCount: number;
140	};
141	
142	const LOYALTY_YEARS = 2;
143	
144	const LOYALTY_DISCOUNT_PERCENT = 20;
145	
146	// Modifier percents are signed so surcharges and discounts can be summed
147	// uniformly; a discount enters the sum as its negation.
148	const asDiscount = (percent: number): number => -percent;
149	
150	const isLoyal = (customer: Customer): boolean =>
151	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
152	
153	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;
154	
155	const isFollowUpContract = (request: QuoteRequest): boolean =>
156	  request.precedingQuoteCount > 0;
157	
158	const policyModifierPercents = (request: QuoteRequest): number[] => [
159	  INITIAL_ASSESSMENT_SURCHARGE_PERCENT,
160	  ...(isLoyal(request.customer) ? [asDiscount(LOYALTY_DISCOUNT_PERCENT)] : []),
161	  ...(isFollowUpContract(request)
162	    ? [asDiscount(FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT)]
163	    : []),
164	];
165	
166	// Policy-wide modifiers do NOT compound: each is an independent percentage of
167	// the policy base premium, and they are summed. Chaining them (base * 1.1 * 0.8)
168	// would give a different, wrong answer.
169	const applyPolicyModifiers = (
170	  basePremium: number,
171	  request: QuoteRequest,
172	): number =>
173	  basePremium +
174	  sumOf(
175	    policyModifierPercents(request).map((percent) =>
176	      percentOf(basePremium, percent),
177	    ),
178	  );
179	
180	const CURSE_SURCHARGE_PERCENT = 50;
181	
182	const HIGH_ENCHANTMENT_LEVEL = 5;
183	
184	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
185	
186	const isHighlyEnchanted = (item: Item): boolean =>
187	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
188	
189	const isCursed = (item: Item): boolean => item.cursed === true;
190	
191	type ItemSurchargeRule = {
192	  applies: (item: Item) => boolean;
193	  percent: number;
194	};
195	
196	const ITEM_SURCHARGE_RULES: ItemSurchargeRule[] = [
197	  { applies: isCursed, percent: CURSE_SURCHARGE_PERCENT },
198	  { applies: isHighlyEnchanted, percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT },
199	];
200	
201	// Item-scoped surcharges are charged on the item's own base premium, so they
202	// must NOT go through applyPolicyModifiers.
203	const itemSurcharges = (item: Item): number =>
204	  sumOf(
205	    ITEM_SURCHARGE_RULES.filter((rule) => rule.applies(item)).map((rule) =>
206	      percentOf(itemBasePremium(item), rule.percent),
207	    ),
208	  );
209	
210	const policyItemSurcharges = (items: Item[]): number =>
211	  sumOf(items.map(itemSurcharges));
212	
213	const quotePremium = (request: QuoteRequest): number =>
214	  roundPremiumInMHPCOsFavor(
215	    applyPolicyModifiers(policyBasePremium(request.items), request) +
216	      policyItemSurcharges(request.items) +
217	      PROCESSING_FEE,
218	  );
219	
220	// --- Claims -----------------------------------------------------------------
221	// An item's insurance value is what it is worth if destroyed, and is unrelated
222	// to its premium: the premium is what the customer pays to be covered. The two
223	// tables below happen to agree on a 10x ratio today, but that is a property of
224	// the current price list and not a rule of the domain — repricing premiums must
225	// not silently revalue payouts, so they stay separate.
226	const INSURANCE_VALUE_BY_TYPE: Record<string, number> = {
227	  sword: 1000,
228	  amulet: 600,
229	  staff: 800,
230	  potion: 400,
231	  rune: 250,
232	  moonstone: 250,
233	};
234	
235	const itemInsuranceValue = (item: Item): number =>
236	  lookUpByItemType(INSURANCE_VALUE_BY_TYPE, item, "insurance value");
237	
238	const insuranceSum = (items: Item[]): number =>
239	  sumOf(items.map(itemInsuranceValue));
240	
241	// A policy pays out at most twice what it insures.
242	const CAP_MULTIPLIER = 2;
243	
244	const policyCap = (items: Item[]): number =>
245	  CAP_MULTIPLIER * insuranceSum(items);
246	
247	const DEDUCTIBLE = 100;
248	
249	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
250	
251	const HALF_REIMBURSEMENT_PERCENT = 50;
252	
253	const isHalfReimbursed = (item: Item): boolean =>
254	  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL;
255	
256	const DRAGON_MATERIAL = "dragon";
257	
258	const isDragonMaterial = (item: Item): boolean =>
259	  item.material === DRAGON_MATERIAL;
260	
261	// A damage entry names the item it damaged by type. The MHPCO only reimburses
262	// what it insured, so a type the policy does not cover is a rejection rather
263	// than an uncovered-but-tolerated entry.
264	const damagedItem = (insuredItems: Item[], damage: Damage): Item => {
265	  const item = insuredItems.find((insured) => insured.type === damage.itemType);
266	
267	  if (item === undefined) {
268	    throw new Error(
269	      `damaged item "${damage.itemType}" is not covered by this policy`,
270	    );
271	  }
272	
273	  return item;
274	};
275	
276	const FULL_REIMBURSEMENT_PERCENT = 100;
277	
278	// A reimbursement clause pays a stated percentage of the damage. Clauses are
279	// listed in precedence order and the first applicable one wins.
280	type ReimbursementClause = {
281	  applies: (item: Item) => boolean;
282	  percent: number;
283	};
284	
285	const REIMBURSEMENT_CLAUSES: ReimbursementClause[] = [
286	  // Half reimbursement outranks the dragon clause: the spec's "50 % rule wins"
287	  // example is a dragon-material item enchanted to 8, and it pays out half.
288	  { applies: isHalfReimbursed, percent: HALF_REIMBURSEMENT_PERCENT },
289	  // "Damage to items made of dragon material is fully reimbursed." This clause
290	  // is currently indistinguishable from the fallback below — every example it
291	  // matches would reimburse in full anyway, so removing it would not change a
292	  // single result, and no test can tell it is here. It is stated regardless
293	  // because it is a rule the domain asserts about dragon material, not an
294	  // accident of what the other rules happen to leave over. Should a future rule
295	  // ever reduce reimbursement below 100 % for some other reason, dragon items
296	  // must keep their full payout, and this line is what will say so.
297	  { applies: isDragonMaterial, percent: FULL_REIMBURSEMENT_PERCENT },
298	];
299	
300	// An item no clause matches is reimbursed in full: that is the domain's
301	// default, not a fallback for a missing item. `damagedItem` now rejects a
302	// damage naming a type the policy does not cover, so there is no such thing
303	// here as an item that isn't there.
304	const reimbursementPercent = (item: Item): number =>
305	  REIMBURSEMENT_CLAUSES.find((clause) => clause.applies(item))?.percent ??
306	  FULL_REIMBURSEMENT_PERCENT;
307	
308	// A damage is something that happened to an item; a negative one is not a
309	// smaller damage but a nonsensical report, so it is rejected rather than
310	// netted off against the rest of the claim.
311	const damageAmount = (damage: Damage): number => {
312	  if (damage.amount < 0) {
313	    throw new Error(
314	      `damage amount ${damage.amount} for "${damage.itemType}" is negative`,
315	    );
316	  }
317	
318	  return damage.amount;
319	};
320	
321	// What a damage entry reimburses before the deductible: a percentage of the
322	// damage amount, decided by the clauses covering the damaged item.
323	const reimbursableAmount = (insuredItems: Item[], damage: Damage): number =>
324	  percentOf(
325	    damageAmount(damage),
326	    reimbursementPercent(damagedItem(insuredItems, damage)),
327	  );
328	
329	// The deductible applies once per damage event, i.e. per entry in `damages`,
330	// and always last — after the clause has decided the reimbursable amount.
331	const damagePayout = (insuredItems: Item[], damage: Damage): number =>
332	  reimbursableAmount(insuredItems, damage) - DEDUCTIBLE;
333	
334	// --- Running a scenario ------------------------------------------------------
335	
336	const isQuote = (step: Step): boolean => step.op === "quote";
337	
338	// What the scenario has accumulated so far. Steps are folded rather than mapped
339	// because a step's result depends on the steps before it: `precedingQuoteCount`
340	// drives the follow-up discount today, and claim steps will thread a remaining
341	// cap through the same carry.
342	// A policy as it stands at some point in the scenario: what it insures, and how
343	// much of its cap is left. The remaining cap belongs to the policy rather than
344	// to a side table because successive claims spend it down — it is the one part
345	// of a policy that changes over the scenario's lifetime.
346	type Policy = {
347	  insuredItems: Item[];
348	  remainingCap: number;
349	};
350	
351	const issuePolicy = (insuredItems: Item[]): Policy => ({
352	  insuredItems,
353	  remainingCap: policyCap(insuredItems),
354	});
355	
356	type ScenarioState = {
357	  results: StepResult[];
358	  precedingQuoteCount: number;
359	  // Policies issued by earlier quote steps, keyed by that step's index — a
360	  // claim names its policy that way (`step.policy`).
361	  policiesByStep: Map<number, Policy>;
362	};
363	
364	const INITIAL_STATE: ScenarioState = {
365	  results: [],
366	  precedingQuoteCount: 0,
367	  policiesByStep: new Map(),
368	};
369	
370	const withPolicy = (
371	  state: ScenarioState,
372	  stepIndex: number,
373	  policy: Policy,
374	): ScenarioState => ({
375	  ...state,
376	  policiesByStep: new Map(state.policiesByStep).set(stepIndex, policy),
377	});
378	
379	// Running a step is a state transition: it reads the carry accumulated by the
380	// preceding steps and returns the next carry. Every step kind gets its own
381	// runner, so `runStep` below is pure dispatch on `op` — the place a claim runner
382	// will be added without touching the quote path.
383	type StepRunner = (
384	  customer: Customer,
385	  state: ScenarioState,
386	  step: Step,
387	  stepIndex: number,
388	) => ScenarioState;
389	
390	const appendResult = (
391	  state: ScenarioState,
392	  result: StepResult,
393	): ScenarioState => ({ ...state, results: [...state.results, result] });
394	
395	const runQuoteStep: StepRunner = (customer, state, step, stepIndex) => {
396	  const items = step.items ?? [];
397	
398	  const premium = quotePremium({
399	    customer,
400	    items,
401	    precedingQuoteCount: state.precedingQuoteCount,
402	  });
403	
404	  return withPolicy(
405	    {
406	      ...appendResult(state, { premium }),
407	      precedingQuoteCount: state.precedingQuoteCount + 1,
408	    },
409	    stepIndex,
410	    issuePolicy(items),
411	  );
412	};
413	
414	// A claim names its policy by the index of the quote step that issued it. A
415	// claim that names no policy, or names one no quote step issued, is not a claim
416	// for 0 G — there is nothing to claim against, so it is rejected. Resolving
417	// yields the key as well as the policy, so that debiting the cap later needs no
418	// second, separately-justified lookup of `step.policy` — the key travelled with
419	// the thing it addresses.
420	type ClaimedPolicy = { key: number; policy: Policy };
421	
422	const claimedPolicy = (state: ScenarioState, step: Step): ClaimedPolicy => {
423	  const key = step.policy;
424	
425	  if (key === undefined) {
426	    throw new Error("claim names no policy");
427	  }
428	
429	  const policy = state.policiesByStep.get(key);
430	
431	  if (policy === undefined) {
432	    throw new Error(`claim against unknown policy ${key}`);
433	  }
434	
435	  return { key, policy };
436	};
437	
438	const countByType = (types: string[]): Map<string, number> => {
439	  const counts = new Map<string, number>();
440	
441	  for (const type of types) {
442	    counts.set(type, (counts.get(type) ?? 0) + 1);
443	  }
444	
445	  return counts;
446	};
447	
448	// Each damage entry is a separate damaged item, so a policy insuring one sword
449	// cannot suffer two sword damages. Over-claiming rejects the whole claim rather
450	// than the offending entry — the MHPCO does not part-settle a suspect report.
451	const rejectOverClaiming = (insuredItems: Item[], damages: Damage[]): void => {
452	  const insuredCounts = countByType(insuredItems.map((item) => item.type));
453	
454	  for (const [itemType, claimed] of countByType(
455	    damages.map((damage) => damage.itemType),
456	  )) {
457	    const insured = insuredCounts.get(itemType) ?? 0;
458	
459	    if (claimed > insured) {
460	      throw new Error(
461	        `claim reports ${claimed} damaged "${itemType}" but the policy covers ${insured}`,
462	      );
463	    }
464	  }
465	};
466	
467	const runClaimStep: StepRunner = (_customer, state, step) => {
468	  const damages = step.incident?.damages ?? [];
469	  const { key, policy } = claimedPolicy(state, step);
470	  const { insuredItems, remainingCap } = policy;
471	
472	  rejectOverClaiming(insuredItems, damages);
473	
474	  // The clamp is outside the per-damage sum: the whole claim is limited by
475	  // what is left of the policy's cap, not each damage individually.
476	  const desiredPayout = sumOf(
477	    damages.map((damage) => damagePayout(insuredItems, damage)),
478	  );
479	  const payout = Math.min(desiredPayout, remainingCap);
480	  const capAfterClaim = remainingCap - payout;
481	
482	  return withPolicy(
483	    appendResult(state, { payout, remainingCap: capAfterClaim }),
484	    key,
485	    { ...policy, remainingCap: capAfterClaim },
486	  );
487	};
488	
489	const runStep: StepRunner = (customer, state, step, stepIndex) =>
490	  isQuote(step)
491	    ? runQuoteStep(customer, state, step, stepIndex)
492	    : runClaimStep(customer, state, step, stepIndex);
493	
494	// The customer is scenario-wide, so it is closed over rather than threaded
495	// through the fold alongside the per-step state.
496	const stepRunnerFor =
497	  (customer: Customer) =>
498	  (state: ScenarioState, step: Step, stepIndex: number) =>
499	    runStep(customer, state, step, stepIndex);
500	
501	export const runScenario = (scenario: Scenario): ScenarioResults => ({
502	  results: scenario.steps.reduce(stepRunnerFor(scenario.customer), INITIAL_STATE)
503	    .results,
504	});
